    @_mutmut_mutated(mutants_xǁWebCrawlerǁ_drain_queue_to_tasks__mutmut)
    def _drain_queue_to_tasks(
        self,
        queue: asyncio.Queue,
        visited: set[str],
        start_url: str,
        hint_lang: str,
        client: httpx.AsyncClient,
        sem: asyncio.Semaphore,
    ) -> set[asyncio.Task]:
        """Dequeue all pending URLs and create fetch tasks for unvisited ones; visited check is safe because no await occurs between check and add."""
        tasks: set[asyncio.Task] = set()
        while not queue.empty():
            url, depth = queue.get_nowait()
            if url in visited or depth > self._max_depth:
                continue
            visited.add(url)
            tasks.add(
                asyncio.create_task(
                    self._process_crawl_url_async(
                        url,
                        depth,
                        start_url,
                        hint_lang,
                        queue,
                        client,
                        sem,
                    ),
                ),
            )
        return tasks

