    @_mutmut_mutated(mutants_xǁWebCrawlerǁ_save_crawl_file__mutmut)
    def _save_crawl_file(
        self,
        url: str,
        title: str,
        lang: str,
        content: str,
        code_blocks: list[str],
        etag: str | None = None,
        last_modified: str | None = None,
    ) -> Path:
        """Save crawl results as JSON to rag-src/yyyymmddhhmmss-{slug}.json."""
        self._rag_src_dir.mkdir(parents=True, exist_ok=True)
        path = self._make_crawl_filepath(url)
        payload: CrawlPayload = {
            "schema_version": "1",
            "artifact_type": "crawl",
            "created_by": "crawler",
            "url": url,
            "title": title,
            "lang": lang,
            "fetched_at": datetime.now().isoformat(timespec="seconds"),
            "content": content,
            "code_blocks": code_blocks,
        }
        if etag is not None:
            payload["etag"] = etag
        if last_modified is not None:
            payload["last_modified"] = last_modified
        path.write_bytes(orjson.dumps(payload, option=orjson.OPT_INDENT_2))
        logger.info(
            "saved",
            extra={"url": url, "source_type": "http"},
        )
        return path

