    def _should_enqueue_link(
        self, a_tag: Tag, current_url: str, start_url: str
    ) -> bool:
        """Check if a link should be enqueued based on nofollow and cross-origin rules."""
        href = a_tag.get("href")
        if not isinstance(href, str):
            return False
        if self._skip_nofollow:
            rel = a_tag.get("rel")
